#!/bin/bash
#==============================================================================
# Chris's Synology - TV Pending Deletions Script
# RUN THIS AFTER tv_sync_actions script completes!
#==============================================================================
# Generated: 2026-01-22 18:04:04
# Total files to delete: 14616
#
# These TV episodes on Chris's Synology have been replaced with better quality
# versions from Ali's Unraid. Run this script to clean up the old files.
#
# Features:
#   - Progress tracking: completed deletions logged and skipped on re-run
#   - Error handling: failures logged with details
#   - DRY_RUN mode to preview deletions first
#
# Usage:
#   DRY_RUN=true ./chris_tv_pending_deletions_XXXXX.sh   # Preview only
#   ./chris_tv_pending_deletions_XXXXX.sh                # Actually delete
#
#==============================================================================

set -o pipefail

PROGRESS_FILE="${PROGRESS_FILE:-chris_tv_deletions_progress_20260122_180402.log}"
ERROR_LOG="${ERROR_LOG:-chris_tv_deletions_errors_20260122_180402.log}"
DRY_RUN="${DRY_RUN:-false}"

# Colors for output
RED="\033[0;31m"
GREEN="\033[0;32m"
YELLOW="\033[0;33m"
BLUE="\033[0;34m"
NC="\033[0m" # No Color

# Statistics
TOTAL=0
DELETED=0
SKIPPED=0
FAILED=0

log() {
    echo -e "[$(date "+%Y-%m-%d %H:%M:%S")] $1"
}

log_error() {
    echo -e "[$(date "+%Y-%m-%d %H:%M:%S")] ${RED}ERROR${NC}: $1" | tee -a "$ERROR_LOG"
}

is_completed() {
    local hash="$1"
    grep -q "^$hash$" "$PROGRESS_FILE" 2>/dev/null
}

mark_completed() {
    local hash="$1"
    echo "$hash" >> "$PROGRESS_FILE"
}

do_delete() {
    local desc="$1"
    local file="$2"
    local hash
    hash=$(echo "$file" | md5sum | cut -d" " -f1)
    
    ((TOTAL++))
    
    if is_completed "$hash"; then
        log "${YELLOW}SKIP${NC} [already done] $desc"
        ((SKIPPED++))
        return 0
    fi
    
    if [ ! -e "$file" ]; then
        log "${YELLOW}SKIP${NC} [not found] $desc"
        mark_completed "$hash"
        ((SKIPPED++))
        return 0
    fi
    
    if [ "$DRY_RUN" = "true" ]; then
        log "${BLUE}[DRY RUN]${NC} Would delete: $desc"
        log "  File: $file"
        ((DELETED++))
        return 0
    fi
    
    log "DELETING: $desc"
    
    if rm -f "$file"; then
        mark_completed "$hash"
        log "${GREEN}DELETED${NC}: $desc"
        ((DELETED++))
    else
        log_error "Failed to delete: $desc"
        log_error "  File: $file"
        ((FAILED++))
    fi
}

print_summary() {
    echo ""
    echo "========================================"
    echo "TV DELETION SUMMARY"
    echo "========================================"
    echo "Total:   $TOTAL"
    echo -e "Deleted: ${GREEN}$DELETED${NC}"
    echo -e "Skipped: ${YELLOW}$SKIPPED${NC}"
    echo -e "Failed:  ${RED}$FAILED${NC}"
    echo "========================================"
    if [ $FAILED -gt 0 ]; then
        echo "See $ERROR_LOG for failure details"
    fi
}

trap print_summary EXIT

log "Starting Chris Synology TV cleanup..."
log "Progress file: $PROGRESS_FILE"
log "Error log: $ERROR_LOG"
if [ "$DRY_RUN" = "true" ]; then
    log "${BLUE}DRY RUN MODE - no files will be deleted${NC}"
fi
echo ""

